// This file is generated by AI.

//! 场景对话抽取。
//!
//! GPT-SoVITS 配音只关心对话语句, 且必须拿到**行号**以便回写。
//!
//! WebGAL 允许省略对话者: 形如 `还没回答。;` 的一行继承其上一条显式说话者语句。
//! 该语法糖在 `Sentence` 层表现为 `speaker = None`, 归属者需由本模块回溯补齐。
//! 补齐后的归属者参与内容哈希, 因此上游说话者行被删除时, 受影响对话的哈希会变化,
//! 前端以此识别 "身份不稳定" 的历史项。

use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

use webgal_language_core::{
    element::FigureId,
    sentence::{PrimarySentence, Sentence},
};

/// 语句身份哈希长度
const HASH_LEN: usize = 12;

/// 一条对话语句
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SayLine {
    /// 行号 (0 起, 即 `scene.lines()` 中的下标)
    pub line: usize,
    /// 该语句占据的行数, 恒为 1
    ///
    /// WebGAL 的语句以整行为单位解析 (见模块文档), 因此不存在跨行语句。
    /// 保留该字段是为了让前端的定位逻辑读起来仍然是"区间", 不必依赖"恒为 1"这个假设。
    pub line_count: usize,
    /// 对话者 (已回溯补齐省略语法; 旁白为 `None`)
    pub speaker: Option<String>,
    /// 对话者是否由上游语句继承而来
    pub speaker_inherited: bool,
    /// 对话内容 (`|` 拼接的多段)
    pub text: String,
    /// 现有配音引用 (`-vocal=` 的值, 相对 `game/vocal/`)
    pub vocal: Option<String>,
    /// 立绘引用 (`-figureId=` 的值或 `-left` 等位置糖, 由 [`FigureId`] 直接给出)
    pub figure: Option<String>,
    /// 语句身份哈希 (对话者 + 内容 + 现有配音)
    pub hash: String,
}

/// 语句改动请求
#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct LineEdit {
    /// 目标行号 (0 起)
    pub line: usize,
    /// 期望的原始内容, 用于写回前的一致性校验; 为 `None` 时跳过校验
    pub expect: Option<String>,
    /// 新的配音引用; `None` 表示移除
    pub vocal: Option<String>,
}

/// 语句改动结果
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct LineEditResult {
    pub line: usize,
    /// 改写后的整行内容
    pub text: String,
}

/// 从场景内容抽取全部对话语句
pub fn parse_say_lines(scene: &str) -> Vec<SayLine> {
    let mut lines = Vec::new();
    let mut current_speaker: Option<String> = None;

    for (index, raw) in scene.lines().enumerate() {
        let output = Sentence::from_str(raw);
        let Sentence::Say(say) = output.sentence else {
            continue;
        };

        let text = say.content.join("|");
        // 空内容占位语句 (`-sayPlaceHolder`, `:;`) 不参与配音
        if text.trim().is_empty() {
            continue;
        }

        // 说话者归属。
        //
        // * `Some(name)` - 显式说话者;
        // * `Some("")` - 显式空说话者 (`:内容;`), 表示旁白, **不继承**;
        // * `None` - 省略说话者的语法糖 (裸 `内容;`), 继承上一条显式说话者。
        let (speaker, speaker_inherited) = match say.speaker {
            Some(speaker) => {
                if !speaker.is_empty() {
                    current_speaker = Some(speaker.clone());
                }
                ((!speaker.is_empty()).then_some(speaker), false)
            }
            None => (current_speaker.clone(), current_speaker.is_some()),
        };

        // `FigureId` 本身就是立绘引用 (id 或位置), 其 `Display` 即 WebGAL 的参数值,
        // 因此不再拆成 "id + side" 两项 —— 那只是同一份信息的两种写法。
        let figure = say.figure.as_ref().map(FigureId::to_string);

        let hash = say_hash(speaker.as_deref(), &text, say.vocal.as_deref());
        lines.push(SayLine {
            line: index,
            line_count: 1,
            speaker,
            speaker_inherited,
            text,
            vocal: say.vocal,
            figure,
            hash,
        });
    }

    lines
}

/// 改写一条语句的配音引用。
///
/// 序列化**直接用 `SaySentence` 的 `Display`**: 设置 `vocal` 字段后 `to_string()`,
/// 再拼上 `PrimarySentence` 里的注释 (它保留注释前导空格, 原样拼回即可)。
pub fn rewrite_line(line: &str, vocal: Option<&str>) -> Result<String, String> {
    let primary = PrimarySentence::from_str(line);
    let mut sentence = Sentence::from_str(line).sentence;
    let Sentence::Say(say) = &mut sentence else {
        return Err("该行不是对话语句".into());
    };
    say.vocal = vocal.map(str::to_string);
    Ok(format!("{say}{}", primary.comment))
}

/// 语句身份哈希: 对话者 + 内容 + 现有配音
pub fn say_hash(speaker: Option<&str>, text: &str, vocal: Option<&str>) -> String {
    let mut hasher = Sha256::new();
    hasher.update(speaker.unwrap_or("").as_bytes());
    hasher.update([0x1f]);
    hasher.update(text.trim().as_bytes());
    hasher.update([0x1f]);
    hasher.update(vocal.unwrap_or("").as_bytes());
    let digest = hasher.finalize();
    digest
        .iter()
        .take(HASH_LEN / 2)
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_dialogue_and_skips_other_statements() {
        let scene = "\
bgm:test.flac;
changeFigure:ext/anon/model.json -id=anon -next;
千早爱音:你爱我吗？ -figureId=anon;
wait:1000;
:爱音躺在沙发上。;
label:loop;
";
        let lines = parse_say_lines(scene);
        assert_eq!(lines.len(), 2);

        assert_eq!(lines[0].line, 2);
        assert_eq!(lines[0].speaker.as_deref(), Some("千早爱音"));
        assert!(!lines[0].speaker_inherited);
        assert_eq!(lines[0].text, "你爱我吗？");
        assert_eq!(lines[0].figure.as_deref(), Some("anon"));

        assert_eq!(lines[1].line, 4);
        assert_eq!(lines[1].speaker, None);
        assert!(lines[1].vocal.is_none());
    }

    #[test]
    fn inherits_speaker_from_previous_explicit_line() {
        let scene = "\
长崎素世:小爱音？ -figureId=soyo;
我有什么不对劲的地方吗？;
:素世抿了一口红茶。;
千早爱音:没...;
反正我就是想问问。;
";
        let lines = parse_say_lines(scene);
        assert_eq!(lines.len(), 5);

        // 显式说话者
        assert_eq!(lines[0].speaker.as_deref(), Some("长崎素世"));
        assert!(!lines[0].speaker_inherited);

        // 省略说话者: 继承上一个显式说话者
        assert_eq!(lines[1].speaker.as_deref(), Some("长崎素世"));
        assert!(lines[1].speaker_inherited);

        // 旁白: 显式空说话者, 不继承
        assert_eq!(lines[2].speaker, None);
        assert!(!lines[2].speaker_inherited);

        // 换人后继续继承
        assert_eq!(lines[3].speaker.as_deref(), Some("千早爱音"));
        assert!(!lines[3].speaker_inherited);
        assert_eq!(lines[4].speaker.as_deref(), Some("千早爱音"));
        assert!(lines[4].speaker_inherited);
    }

    #[test]
    fn narration_after_explicit_speaker_is_not_inherited() {
        let scene = "爱音:对话;\n:旁白;\n";
        let lines = parse_say_lines(scene);
        assert_eq!(lines.len(), 2);
        assert_eq!(lines[0].speaker.as_deref(), Some("爱音"));
        // `:旁白;` 是显式空说话者, 不继承前面的爱音
        assert_eq!(lines[1].speaker, None);
        assert!(!lines[1].speaker_inherited);
    }

    #[test]
    fn narration_does_not_reset_inheritance_before_any_speaker() {
        let scene = ":第一句旁白;\n:第二句旁白;\n";
        let lines = parse_say_lines(scene);
        assert_eq!(lines.len(), 2);
        assert!(lines.iter().all(|line| line.speaker.is_none()));
        assert!(lines.iter().all(|line| !line.speaker_inherited));
    }

    #[test]
    fn skips_empty_and_placeholder_lines() {
        let scene = ":;\n: ;\n爱音: -sayPlaceHolder;\n爱音:真的有内容;\n";
        let lines = parse_say_lines(scene);
        assert_eq!(lines.len(), 1);
        assert_eq!(lines[0].text, "真的有内容");
    }

    #[test]
    fn joins_multiline_content() {
        let scene = "爱音:第一段|第二段;\n";
        let lines = parse_say_lines(scene);
        assert_eq!(lines[0].text, "第一段|第二段");
    }

    #[test]
    fn records_existing_vocal_and_side() {
        let scene = "爱音:内容 -vocal=anon/a1.wav -left;\n";
        let lines = parse_say_lines(scene);
        assert_eq!(lines[0].vocal.as_deref(), Some("anon/a1.wav"));
        assert_eq!(lines[0].figure.as_deref(), Some("fig-left"));
    }

    #[test]
    fn hash_depends_on_speaker_text_and_vocal() {
        let base = say_hash(Some("爱音"), "内容", None);
        assert_eq!(base, say_hash(Some("爱音"), "内容", None));
        assert_eq!(base.len(), HASH_LEN);
        // 内容首尾空白不影响
        assert_eq!(base, say_hash(Some("爱音"), "  内容  ", None));
        // 说话者变化影响 (身份不稳定场景)
        assert_ne!(base, say_hash(Some("素世"), "内容", None));
        // 内容变化影响
        assert_ne!(base, say_hash(Some("爱音"), "内容2", None));
        // 现有配音变化影响
        assert_ne!(base, say_hash(Some("爱音"), "内容", Some("anon/a.wav")));
        // 旁白与对话者区分
        assert_ne!(base, say_hash(None, "内容", None));
    }

    #[test]
    fn rewrite_sets_vocal_and_keeps_other_parts() {
        let line = "千早爱音:你爱我吗？ -figureId=anon -when=a>1; 这是注释";
        let rewritten = rewrite_line(line, Some("anon/a1b2c3.wav")).unwrap();
        // 走 `SaySentence` 的 `Display`: 普通路径写成裸参数 (引擎接受的写法)
        assert_eq!(
            rewritten,
            "千早爱音:你爱我吗？ -anon/a1b2c3.wav -figureId=anon -when=a>1; 这是注释"
        );
    }

    #[test]
    fn rewrite_replaces_existing_vocal() {
        let line = "爱音:内容 -vocal=old.wav;";
        let rewritten = rewrite_line(line, Some("new.wav")).unwrap();
        assert_eq!(rewritten, "爱音:内容 -new.wav;");
        assert!(!rewritten.contains("old.wav"));
    }

    #[test]
    fn rewrite_removes_vocal() {
        let line = "爱音:内容 -vocal=old.wav -figureId=anon;";
        let rewritten = rewrite_line(line, None).unwrap();
        assert!(!rewritten.contains("old.wav"));
        assert!(rewritten.contains("-figureId=anon"));
    }

    #[test]
    fn rewrite_roundtrips_narration() {
        let line = ":爱音躺在沙发上。;";
        let rewritten = rewrite_line(line, Some("narration/a1.wav")).unwrap();
        assert!(rewritten.contains(":爱音躺在沙发上。"));
        assert!(rewritten.contains("-narration/a1.wav"));
    }

    #[test]
    fn rewrite_rejects_non_dialogue() {
        assert!(rewrite_line("bgm:test.flac;", Some("a.wav")).is_err());
        assert!(rewrite_line("changeFigure:model.json -id=anon;", Some("a.wav")).is_err());
    }

    #[test]
    fn rewrite_preserves_nolint() {
        let line = "爱音:内容 -vocal=old.wav;nolint:WG001; 备注";
        let rewritten = rewrite_line(line, Some("new.wav")).unwrap();
        assert!(rewritten.contains("nolint:WG001"));
        assert!(rewritten.contains("备注"));
        assert!(rewritten.contains("-new.wav"));
    }

    #[test]
    fn statement_span_counts_multiline_statements() {
        // 语句恒为单行: 未以分号结尾的行不会把后续行"吞"进同一条语句。
        // 这一点必须钉住 —— 曾经用"找第一个分号"推测语句跨度, 导致光标停在
        // 缺分号的行上时会命中**上一条**对话。
        let scene = "\
爱音:第一行
第二行;
爱音:没有分号
爱音:正常;
";
        let lines = parse_say_lines(scene);
        assert_eq!(
            lines.iter().map(|item| item.line).collect::<Vec<_>>(),
            vec![0, 1, 2, 3]
        );
        assert!(lines.iter().all(|item| item.line_count == 1));
    }

    #[test]
    fn line_count_is_reported_for_each_dialogue() {
        // 逐行解析: 每一条对话就是一行
        let scene = "爱音:你爱我吗？;\n长崎素世:唉？;\nnext:对话;\n";
        let lines = parse_say_lines(scene);
        assert_eq!(lines.len(), 3);
        assert!(lines.iter().all(|item| item.line_count == 1));

        // 内容里出现转义分号时仍按单行处理
        let escaped = parse_say_lines("爱音:含\\;分号;\n");
        assert_eq!(escaped.len(), 1);
        assert_eq!(escaped[0].line_count, 1);
    }

    #[test]
    fn figure_is_reported_as_its_display_value() {
        // 立绘 id 与位置糖用同一个字段表示 (`FigureId` 的 Display)
        let id = parse_say_lines("爱音:内容 -figureId=anon;\n");
        assert_eq!(id[0].figure.as_deref(), Some("anon"));

        let side = parse_say_lines("爱音:内容 -left;\n");
        assert_eq!(side[0].figure.as_deref(), Some("fig-left"));

        let none = parse_say_lines("爱音:内容;\n");
        assert_eq!(none[0].figure, None);
    }

    #[test]
    fn dialogue_lines_mix_into_realistic_scene() {
        // 手写的仿真场景: 覆盖真实项目里常见的形态 ——
        // 资源语句、`:;` 占位、旁白、带立绘的台词、省略说话者的裸行、带参数的台词。
        let scene = "\
bgm:The des Alizes.flac;
changeBg:角色生活地点/素世家客厅（晚上）.png -next;
changeFigure:ext/居家服素世/model.json -left -id=soyo -motion=soyo_nf03 -next;
:;
:爱音躺在沙发上，如往常一样翻看着手机。;
长崎素世:小爱音？ -figureId=soyo;
setTransform:{\"position\":{\"x\":0}} -target=bg-main -next;
长崎素世:我有什么不对劲的地方吗？ -figureId=soyo;
千早爱音:没... -figureId=anon;
:;
:在安静持续了十几秒后，爱音又忍不住开口了。;
千早爱音:你爱我吗？ -figureId=anon;
";
        let lines = parse_say_lines(scene);

        // 只有对话语句入选, 且每行一条
        assert_eq!(
            lines.iter().map(|item| item.line).collect::<Vec<_>>(),
            vec![4, 5, 7, 8, 10, 11]
        );
        assert!(lines.iter().all(|item| item.line_count == 1));

        // 第 4 行旁白 (显式空说话者, 不继承)
        assert_eq!(lines[0].speaker, None);
        assert!(!lines[0].speaker_inherited);
        assert_eq!(lines[0].text, "爱音躺在沙发上，如往常一样翻看着手机。");

        // 第 6 行带 figureId 的台词
        assert_eq!(lines[1].speaker.as_deref(), Some("长崎素世"));
        assert_eq!(lines[1].figure.as_deref(), Some("soyo"));

        // 第 8 行台词, 第 9 行是省略说话者的裸行 (继承爱音)
        assert_eq!(lines[3].speaker.as_deref(), Some("千早爱音"));
        assert!(!lines[3].speaker_inherited);

        // 第 11 行旁白同样不继承之前的说话者
        assert_eq!(lines[4].speaker, None);
        assert!(!lines[4].speaker_inherited);

        // 资源语句与占位语句都不出现
        assert!(lines
            .iter()
            .all(|item| !matches!(item.line, 0 | 1 | 2 | 3 | 6 | 9)));
    }

    #[test]
    fn parsed_lines_roundtrip_vocal_through_rewrite() {
        let scene = "爱音:你爱我吗？ -figureId=anon;\n:素世愣住了;\n";
        let lines = parse_say_lines(scene);
        let rewritten =
            rewrite_line("爱音:你爱我吗？ -figureId=anon;", Some("anon/x.wav")).unwrap();
        let reparsed = parse_say_lines(&rewritten);
        assert_eq!(reparsed.len(), 1);
        assert_eq!(reparsed[0].vocal.as_deref(), Some("anon/x.wav"));
        // 内容与说话者不变
        assert_eq!(reparsed[0].text, lines[0].text);
        assert_eq!(reparsed[0].speaker, lines[0].speaker);
        // 哈希随配音引用变化
        assert_ne!(reparsed[0].hash, lines[0].hash);
    }
}
